// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: index < 10 ? 3 : index < 20 ? 4 : 5,
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + ' классы',
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + grade + '.pdf',
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf',
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2016, "2-3", [{"author":"Е. Добрушина","question":"На полянке беседовали пять разных друзей-животных. Первый спросил:\n«Кудах-тах-тах?». Ему ответил второй: «Ква-ква-ква». На это третий возразил:\n«Чик-чирик!» С ним согласился четвёртый: «Му-у-у!». И только пятый промолчал. Кто это был?","choices":["<em>утка</em>","<em>курица</em>","<em>корова</em>","<em>воробей</em>","<em>лягушка</em>."],"key":"А","review":["Беседа на полянке","По голосам узнаём четырёх друзей. Курица кудахчет, лягушка квакает, воробей чирикает, а корова мычит.","Из списка остаётся утка. Её «кря-кря» в беседе не прозвучало."]},{"author":"Б. Иомдин","question":"Каким из этих знаков чаще всего заканчиваются предложения?","choices":["!","!!!",".","?","???"],"key":"В","review":["Знак в конце предложения","Сравни «Снег идёт.», «Снег идёт?» и «Снег идёт!». В первом случае просто сообщают новость, во втором спрашивают, в третьем восклицают.","Обычные сообщения встречаются чаще вопросов и восклицаний. В конце таких предложений ставят точку."]},{"author":"Б. Иомдин и А. Пиперски","question":"На уроке проходили правила переноса. Саше стало скучно, он закрасил приставку в слове <em>перенос</em> и получил слово <em>нос</em>. Тогда он стал закрашивать приставку <em>пере</em>- и в других случаях, пытаясь получить осмысленные слова. А с каким словом это не вышло?","choices":["<em>переход</em>","<em>перевал</em>","<em>перепад</em>","<em>перебор</em>","<em>перевес</em>."],"key":"В","review":["Сашины приставки","Убери одинаковую часть «пере-». Из «перехода», «перевала», «перебора» и «перевеса» получаются знакомые слова «ход», «вал», «бор» и «вес».","Из «перепада» получается «пад». В этом задании нужно самостоятельное слово, а «пад» здесь только часть слова «перепад»."]},{"author":"С. Бурлак","question":"Решила Света сочинить сказку. Придумала три первых предложения:\n1) А её дома не оказалось.\n2) Прилетел однажды Змей Горыныч к избушке на курьих ножках.\n3) Он хотел к Бабе-яге в гости зайти.\nРасставьте их в правильном порядке:","choices":["1, 2, 3","2, 3, 1","3, 1, 2","2, 1, 3","1, 3, 2."],"key":"Б","review":["Начало Светиной сказки","Найди предложение, где сказка знакомит нас с героем. В предложении 2 назван Змей Горыныч, поэтому в следующем предложении его уже можно назвать «он».","В предложении 3 Змей собирается к Бабе-яге, а в предложении 1 выясняется, что «её» нет дома. Порядок такой — 2, 3, 1."]},{"author":"Е. Муравенко","question":"Вот первые части двусложных слов: <em>ут</em>-, <em>мет-</em>, <em>вет</em>-, а вот вторые: -<em>ро</em>, <em>-ка</em>. Сколько слов можно получить, соединяя первые части со вторыми?","choices":["два","три","четыре","пять","шесть."],"key":"Г","review":["Слова из двух частей","Присоедини «-ка» к каждой первой части. Получится три слова — «утка», «метка» и «ветка».","Теперь присоедини «-ро». Получатся ещё два слова, «утро» и «метро». Слова «ветро» нет, поэтому всего слов пять."]},{"author":"И. Леенсон","question":"Какое слово называет <strong>не</strong> птенца?","choices":["<em>журавлёнок</em>","<em>утёнок</em>","<em>опёнок</em>","<em>цыплёнок</em>","<em>орлёнок</em>."],"key":"В","review":["Кто вылупился из яйца","Свяжи названия с птицами. У журавля птенец журавлёнок, у утки — утёнок, у курицы — цыплёнок, у орла — орлёнок.","Слово «опёнок» обозначает гриб. Его название связано с пнём, на котором могут расти такие грибы."]},{"author":"Е. Муравенко","question":"Собака, лошадь, медведь, аист.\nГде никто из них не живёт?","choices":["в дупле","в гнезде","в берлоге","в конуре","в конюшне."],"key":"А","review":["Жилища животных","Подбери каждому жильца. Собаке подходит конура, лошади — конюшня, медведю — берлога, аисту — гнездо.","В этом перечне привычных жилищ остаётся дупло, то есть полость в дереве. Оно могло бы подойти, например, белке."]},{"author":"Е. Добрушина","question":"Сказочный принц живёт за зубчатой стеной с башнями по углам и бойницами. Стена окружена рвом с подъёмным мостом. Как лучше всего назвать место, где живёт принц?","choices":["<em>дворец</em>","<em>замок</em>","<em>усадьба</em>","<em>терем</em>","<em>трактир</em>."],"key":"Б","review":["Где живёт принц","Отметь детали, которые помогают защищаться. Из бойниц можно стрелять, ров мешает добраться до стены, а подъёмный мост закрывает путь внутрь.","Укреплённое жилище с башнями, стеной и рвом называют замком. По таким деталям его можно узнать, даже если бы про принца ничего не сказали."]},{"author":"Л. Фёдорова","question":"<em>Вольке выпала большая удача. Ему всегда</em> ... .","choices":["<em>падает</em>","<em>идёт</em>","<em>летит</em>","<em>рулит</em>","<em>везёт</em>."],"key":"Д","review":["Волькина удача","Подставь вместо пропуска слова «сопутствует удача». Тогда вторая фраза объяснит, что счастливый случай у Вольки случается часто.","По-русски в таком смысле говорят «ему везёт». Например, если Волька часто выигрывает, можно сказать «Вольке всегда везёт»."]},{"author":"Б. Иомдин","question":"Что бывает у дома, но не бывает у квартиры?","choices":["дверь","потолок","крыша","окно","стена."],"key":"В","review":["Дом и квартира","Мысленно пройдись по квартире. В ней есть дверь, окно, стены и потолок, как и в доме.","Крыша закрывает здание сверху, включая все квартиры под ней. Она относится ко всему дому, а внутри отдельной квартиры сверху виден потолок."]},{"author":"А. Панина","question":"Как нельзя заполнить пропуск?\n<em>Котёнок ____ высунулся из-под шкафа</em>.","choices":["<em>осторожно</em>","<em>боязно</em>","<em>боязливо</em>","<em>опасливо</em>","<em>с опаской</em>."],"key":"Б","review":["Котёнок под шкафом","Задай вопрос «как высунулся?». Подходят «осторожно», «боязливо», «опасливо» и «с опаской». Все они объясняют, как котёнок двигался.","Словом «боязно» обычно называют чувство страха в фразах вроде «Котёнку боязно выглядывать». В данное предложение его подставить нельзя."]},{"author":"А. Лопухина","question":"Название какого месяца начинается с той же буквы, что и его номер?","choices":["<em>январь</em>","<em>апрель</em>","<em>сентябрь</em>","<em>октябрь</em>","<em>декабрь</em>."],"key":"Д","review":["Месяцы по порядку","Запиши номера месяцев словами. Январь — первый, апрель — четвёртый, сентябрь — девятый, октябрь — десятый, декабрь — двенадцатый.","У первых четырёх пар начальные буквы разные. Только «декабрь» и «двенадцатый» оба начинаются с «д»."]},{"author":"С. Переверзева","question":"Название какой из этих игрушек звучит как призыв к какому-то действию?","choices":["<em>матрёшка</em>","<em>погремушка</em>","<em>пирамидка</em>","<em>лошадь-качалка</em>","<em>ванька-встанька</em>."],"key":"Д","review":["Имена игрушек","Вслушайся в названия. «Матрёшка» и «пирамидка» называют игрушки, а «погремушка» и «лошадь-качалка» ещё дают понять, что игрушки могут делать.","В «ваньке-встаньке» слышится обращение «Ванька, встань!». Слово «встань» звучит как просьба или команда."]},{"author":"С. Переверзева","question":"На старом пузырьке Алиса увидела полустёршуюся надпись:\n«4 таблеток». «Наверное, — подумала она, — перед 4 должна была стоять ещё одна цифра, и это цифра …».","choices":["9","5","3","2","1."],"key":"Д","review":["Надпись на пузырьке","Прочитай надпись с разными цифрами. «Двадцать четыре таблетки», «тридцать четыре таблетки», «пятьдесят четыре таблетки» и «девяносто четыре таблетки» требуют формы «таблетки».","С числом 14 говорят «четырнадцать таблеток». Это единственное из предложенных чисел, которому подходит сохранившееся слово, поэтому стёрлась цифра 1."]},{"author":"Л. Фёдорова","question":"В школу поступили львёнок, ягнёнок, утёнок и телёнок. Их записали под фамилиями: Львов, Баранов, Селезнёв и … .","choices":["Коровин","Быков","Телёнков","Тёлушкин","Телятин."],"key":"Б","review":["Фамилии для зверят","Сравни три фамилии с названиями зверей. Львов связан со львом, Баранов — с бараном, Селезнёв — с селезнем, то есть самцом утки.","По тому же правилу бери название взрослого самца для телёнка. Это бык, значит, фамилия будет Быков."]},{"author":"О. Подлесская","question":"В книге Бориса Житкова о мальчике Алёшке читаем:\n«Бабушка на меня поглядела. Очень сильно на меня поглядела. Я вспомнил и сказал:\n— …, дедушка.\nА дедушка говорит:\n— На здоровье».\nЧто мы пропустили?","choices":["<em>Здравствуй</em>","<em>Будь здоров</em>","<em>Добрый день</em>","<em>Спасибо</em>","<em>Пожалуйста</em>."],"key":"Г","review":["Ответ дедушки","Начни с ответа дедушки. «На здоровье» нередко говорят, когда кого-то угостили или сделали для него что-то полезное.","Представь короткий разговор «Спасибо, дедушка. — На здоровье». Приветствия из вариантов ожидают ответного приветствия, а здесь подошла благодарность."]},{"author":"Б. Иомдин","question":"Название какой еды не говорит о том, как её готовят?","choices":["<em>вареники</em>","<em>запеканка</em>","<em>мороженое</em>","<em>печёнка</em>","<em>тушёнка</em>."],"key":"Г","review":["Названия еды","Подбери глаголы приготовления. Вареники варят, запеканку запекают, мороженое замораживают, тушёнку тушат.","Печёнкой называют печень, которую можно, к примеру, пожарить или потушить. По её названию способ приготовления определить нельзя."]},{"author":"С. Бурлак","question":"Найдите среди этих слов самое длинное, которое нельзя переносить.","choices":["<em>поэма</em>","<em>идея</em>","<em>конь</em>","<em>огонь</em>","<em>ошибка</em>."],"key":"Г","review":["Самое длинное без переноса","Переносить можно части с гласной, если ни одна буква не остаётся в одиночку. Подходят «по-эма» и «ошиб-ка». У односложного слова «конь» переноса нет.","В «идея» перенос «и-дея» оставит букву и, а «иде-я» — букву я. В «огонь» единственный возможный по слогам разрез «о-гонь» оставит одну о. Из слов без переноса «огонь» самое длинное: пять букв."]},{"author":"Б. и М. Иомдины","question":"Два урока подряд Макс баловался, а на третьем наконец … .","choices":["<em>примирился</em>","<em>утихомирился</em>","<em>смирился</em>","<em>помирился</em>","<em>замирился.</em>"],"key":"Б","review":["Макс на третьем уроке","Вторая часть предложения противопоставлена первой. Если Макс два урока баловался, то слово «наконец» подсказывает, что на третьем он успокоился.","Именно «утихомирился» значит «перестал шуметь и баловаться». Слова «помирился» и «примирился» уместны при ссоре, а «смирился» — когда кто-то принял неприятное положение."]},{"author":"Л. Фёдорова","question":"Утроением знаков в китайском письме изначально передавались слова с новым значением, например: 石 ‘камень’ <em>—</em> 磊 ‘груда камней’; 隹 ‘птица’ <em>—</em> 雥 ‘стая птиц’; 马 ‘лошадь’ <em>—</em> 骉 ‘табун лошадей’. Найдите переводы иероглифов 森, 众, 飍, если известно, что 木 <em>— дерево</em>, 人 <em>— человек</em>, 風 <em>— ветер</em>.","choices":["<em>дом</em>, <em>семья</em>, <em>парус</em>","<em>куст</em>, <em>ребёнок</em>, <em>безветрие</em>","<em>аллея</em>, <em>дети</em>, <em>пыль</em>","<em>дуб</em>, <em>толстяк</em>, <em>сквозняк</em>","<em>чаща</em>, <em>толпа</em>, <em>ураган</em>."],"key":"Д","review":["Три знака в иероглифе","Посмотри, как работают примеры. Из трёх знаков «камень» получается груда камней, из трёх «птиц» — стая, из трёх «лошадей» — табун.","У «дерева» множество деревьев даёт чащу, у «человека» множество людей даёт толпу, а утроенный «ветер» передаёт сильный ветер, ураган."]},{"author":"И. Погодаев","question":"В комнате сидят десять человек: Вова, Илья, Женя, Саша, Сима,\nСерёжа, Валя, Игорь, Лёва и Таня.\nКакое утверждение точно неверно?","choices":["в комнате больше четырёх мальчиков","в комнате есть три девочки","в комнате мальчиков больше, чем девочек","в комнате поровну девочек и мальчиков","в комнате больше пяти девочек."],"key":"Д","review":["Имена десяти ребят","Отметь тех, кого можно уверенно посчитать мальчиками. Это Вова, Илья, Серёжа, Игорь и Лёва. Таня — девочка, а Женя, Саша, Сима и Валя могут быть и мальчиками, и девочками.","Даже если четыре имени с двумя возможностями принадлежат девочкам, их вместе с Таней будет только пять. Поэтому утверждение «больше пяти девочек» точно неверно."]},{"author":"Е. Бикмаев","question":"В какой пример можно вставить букву так, чтобы получилось слово?","choices":["<em>жь_жь</em>","<em>шь_шь</em>","<em>щь_щь</em>","<em>ць_ць</em>","<em>чь_чь.</em>"],"key":"Б","review":["Пропущенная буква","Рассмотри, какое слово может начинаться на «шь» и так же оканчиваться. Подходит форма глагола «шить», если сказать, что делаешь это ты.","Вставь «ё» между двумя «шь». Получится «шьёшь», как в предложении «Ты шьёшь платье»."]},{"author":"А. Сомин","question":"Петя прочитал в белорусской книге:\n<em>— Віктар, які букет! Званочкі! Я так іх люблю, — усклікнула Паліна.</em> А какие цветы подарил Виктор Полине?","choices":["колокольчики","одуванчики","васильки","ромашки","подснежники."],"key":"А","review":["Викторов букет","Фраза «Я так іх люблю» означает «Я так их люблю». Полина смотрит на букет, поэтому белорусское «званочкі» называет цветы в нём.","Услышь в «званочкі» слово, похожее на «звоночки». Из перечисленных цветов маленькие колокола напоминают колокольчики."]},{"author":"И. Скоморохова","question":"Какое слово здесь зашифровано?","choices":["<em>ключ</em>","<em>мост</em>","<em>стол</em>","<em>плюс</em>","<em>ромб</em>."],"key":"Б","review":["Рисунок с шифром","Верхняя рамка содержит все нужные линии. Для первого знака мысленно сотри из рамки штрихи первой нижней фигурки. Останутся две боковые стороны и две наклонные линии от верхних углов к середине — буква М.","Повтори это для трёх других фигурок. Останутся прямоугольник О, открытая справа С и верхняя черта со стойкой Т. Читай слева направо — МОСТ."],"figure":{"condition":{"src":"assets/medvezhonok/2016/2-3-24.webp","width":999,"height":206,"pixelWidth":999,"pixelHeight":206,"alt":"Сверху прямоугольник с горизонталью, вертикалью и двумя диагоналями через центр. Под ним четыре рисунка. На первом три горизонтали, средняя вертикаль и линии от центра к нижним углам. На втором средняя горизонталь, средняя вертикаль и обе диагонали. На третьем средняя горизонталь, средняя и правая вертикали и обе диагонали. На четвёртом средняя и нижняя горизонтали, обе боковые вертикали и обе диагонали."}}},{"author":"Е. Муравенко","question":"В какой паре слова связаны по смыслу не так, как во всех остальных парах?","choices":["<em>рисовать — рисунок</em>","<em>чертить — чертёж</em>","<em>красить — краска</em>","<em>вышивать — вышивка</em>","во всех парах (А)‒(Г) слова по смыслу связаны одинаково."],"key":"В","review":["Действие и его пара","Спроси, что получается после действия. После рисования остаётся рисунок, после черчения — чертёж, после вышивания — вышивка.","При покраске краску берут заранее и наносят на поверхность. Она служит материалом, поэтому пара «красить — краска» устроена иначе."]},{"author":"Б. и М. Иомдины","question":"У Ренаты Мухи есть стихотворения-«недоговорки». К какому из них название «недоговорка» подходит меньше, чем к остальным?","choices":["Один Верблюд, кипя от злобы,\nВчера ушел в пустыню, чтобы","Как-то раз у Короля\nНе хватило денег для","Как-то раз в одной стране\nВсе решили больше не","Едет Окунь на Коне.\nКонь доволен, Окунь не","Ко всем этим стихотворениям название «недоговорка» подходит одинаково."],"key":"Г","review":["Стихи-недоговорки","Попробуй закончить первые три стиха. После «чтобы» не хватает цели, после «для» — того, на что нужны деньги, а после «не» — действия, от которого решили отказаться.","В стихе про Окуня недостающее слово уже было в той же строке. «Конь доволен, Окунь не» легко понять как «Окунь не доволен», поэтому этот стих звучит более законченным."]},{"author":"Б. Иомдин","question":"В интернете несколько десятков раз встречается слово <em>торовиш.</em>\nА какое слово чаще всего встречается рядом с ним?","choices":["<em>непонятный</em>","<em>норовишь</em>","<em>тороватый</em>","<em>торовыван</em>","<em>тоторовиш.</em>"],"key":"Г","review":["Загадочное слово в сети","Прочитай «торовиш» справа налево. Получится знакомое «шиворот», а с ним часто звучит «навыворот».","Запиши «навыворот» в обратном порядке. Получишь «торовыван» — вторую половину перевёрнутого выражения «шиворот-навыворот»."]},{"author":"Е. Муравенко","question":"В книжке Александра Шибаева про русский язык читаем:\n«Есть волшебные слова: скажешь слово — слышишь два».\nНапример:\nОчень сыро-сыро-сыро\nОт росы-росы-росы.\nА вот ещё четыре волшебных слова из этой книжки и одно неволшебное. Какое неволшебное?","choices":["<em>навес</em>","<em>камыш</em>","<em>банка</em>","<em>купил</em>","<em>кивну</em>."],"key":"А","review":["Волшебные слова Шибаева","Повтори каждое слово без пауз. Слушай, что выходит на стыке повторов. Так слышно «мы́шка» из «камы́ш», «каба́н» из «ба́нка», «пи́лку» из «купи́л» и «вну́ки» из «кивну́».","В цепочке из «наве́с» тоже видны буквы «весна», но ударение в ней будет «ве́сна». В слове «весна́» оно падает на другой слог, так что на слух фокус не получается."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
